import { View, Text, Pressable{{#if (eq styling "stylesheet")}}, StyleSheet{{/if}} } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import MapView, { Marker } from 'react-native-maps';
{{#if (eq icons "lucide")}}
import { Navigation, Layers, Crosshair } from 'lucide-react-native';
{{/if}}
import { LocationSheet } from '../../components/LocationSheet';

const markers = [
  { id: '1', title: 'Coffee Shop', coordinate: { latitude: 37.78825, longitude: -122.4324 }, description: 'Best espresso in town' },
  { id: '2', title: 'Park', coordinate: { latitude: 37.78925, longitude: -122.4344 }, description: 'Morning jogging spot' },
  { id: '3', title: 'Office', coordinate: { latitude: 37.78725, longitude: -122.4304 }, description: 'Main workspace' },
];

export default function MapScreen() {
  return (
    <View {{#if (eq styling "nativewind")}}className="flex-1"{{else}}style={styles.container}{{/if}}>
      <MapView
        style=\{{ flex: 1 }}
        initialRegion=\{{
          latitude: 37.78825,
          longitude: -122.4324,
          latitudeDelta: 0.01,
          longitudeDelta: 0.01,
        }}
        showsUserLocation
      >
        {markers.map((marker) => (
          <Marker
            key={marker.id}
            coordinate={marker.coordinate}
            title={marker.title}
            description={marker.description}
          />
        ))}
      </MapView>

      {/* Floating Controls */}
      <SafeAreaView style={styles.controls} edges={['top']}>
        <View {{#if (eq styling "nativewind")}}className="absolute right-4 top-4 gap-3"{{else}}style={styles.floatingControls}{{/if}}>
          {{#if (eq icons "lucide")}}
          <Pressable {{#if (eq styling "nativewind")}}className="h-10 w-10 items-center justify-center rounded-full bg-white shadow-lg"{{else}}style={styles.controlButton}{{/if}}>
            <Layers size={20} color="#374151" />
          </Pressable>
          <Pressable {{#if (eq styling "nativewind")}}className="h-10 w-10 items-center justify-center rounded-full bg-white shadow-lg"{{else}}style={styles.controlButton}{{/if}}>
            <Crosshair size={20} color="#374151" />
          </Pressable>
          {{/if}}
        </View>
      </SafeAreaView>

      {/* Bottom Sheet */}
      <LocationSheet
        name="Coffee Shop"
        address="123 Main St, San Francisco, CA"
        rating={4.8}
        distance="0.3 mi"
      />
    </View>
  );
}

{{#if (eq styling "stylesheet")}}
const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
  controls: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
  },
  floatingControls: {
    position: 'absolute',
    right: 16,
    top: 16,
    gap: 12,
  },
  controlButton: {
    height: 40,
    width: 40,
    alignItems: 'center',
    justifyContent: 'center',
    borderRadius: 20,
    backgroundColor: '#FFFFFF',
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.1,
    shadowRadius: 4,
    elevation: 3,
  },
});
{{/if}}

import { View, Text, Pressable{{#if (eq styling "stylesheet")}}, StyleSheet{{/if}} } from 'react-native';
{{#if (eq icons "lucide")}}
import { Star, Navigation, Phone, Bookmark } from 'lucide-react-native';
{{/if}}
{{#if typescript}}
type LocationSheetProps = {
  name: string;
  address: string;
  rating: number;
  distance: string;
};
{{/if}}

export function LocationSheet({ name, address, rating, distance }{{#if typescript}}: LocationSheetProps{{/if}}) {
  return (
    <View {{#if (eq styling "nativewind")}}className="absolute bottom-0 left-0 right-0 rounded-t-3xl bg-white px-5 pt-4 pb-8"{{else}}style={styles.container}{{/if}}>
      {/* Handle */}
      <View {{#if (eq styling "nativewind")}}className="mb-4 items-center"{{else}}style={styles.handleContainer}{{/if}}>
        <View {{#if (eq styling "nativewind")}}className="h-1 w-10 rounded-full bg-gray-300"{{else}}style={styles.handle}{{/if}} />
      </View>

      {/* Content */}
      <View {{#if (eq styling "nativewind")}}className="flex-row items-start justify-between"{{else}}style={styles.header}{{/if}}>
        <View {{#if (eq styling "nativewind")}}className="flex-1"{{else}}style={styles.headerContent}{{/if}}>
          <Text {{#if (eq styling "nativewind")}}className="text-xl font-bold text-gray-900"{{else}}style={styles.name}{{/if}}>
            {name}
          </Text>
          <Text {{#if (eq styling "nativewind")}}className="mt-1 text-sm text-gray-500"{{else}}style={styles.address}{{/if}}>
            {address}
          </Text>
          <View {{#if (eq styling "nativewind")}}className="mt-2 flex-row items-center gap-4"{{else}}style={styles.meta}{{/if}}>
            {{#if (eq icons "lucide")}}
            <View {{#if (eq styling "nativewind")}}className="flex-row items-center"{{else}}style={styles.ratingRow}{{/if}}>
              <Star size={14} color="#F59E0B" fill="#F59E0B" />
              <Text {{#if (eq styling "nativewind")}}className="ml-1 text-sm font-medium text-gray-700"{{else}}style={styles.rating}{{/if}}>
                {rating}
              </Text>
            </View>
            {{/if}}
            <Text {{#if (eq styling "nativewind")}}className="text-sm text-gray-400"{{else}}style={styles.distance}{{/if}}>
              {distance}
            </Text>
          </View>
        </View>
        {{#if (eq icons "lucide")}}
        <Pressable {{#if (eq styling "nativewind")}}className="h-10 w-10 items-center justify-center rounded-full bg-gray-100"{{else}}style={styles.bookmarkButton}{{/if}}>
          <Bookmark size={20} color="#6B7280" />
        </Pressable>
        {{/if}}
      </View>

      {/* Actions */}
      <View {{#if (eq styling "nativewind")}}className="mt-5 flex-row gap-3"{{else}}style={styles.actions}{{/if}}>
        <Pressable {{#if (eq styling "nativewind")}}className="flex-1 flex-row items-center justify-center gap-2 rounded-xl bg-blue-600 py-3"{{else}}style={styles.primaryButton}{{/if}}>
          {{#if (eq icons "lucide")}}
          <Navigation size={18} color="#FFFFFF" />
          {{/if}}
          <Text {{#if (eq styling "nativewind")}}className="font-semibold text-white"{{else}}style={styles.primaryButtonText}{{/if}}>
            Directions
          </Text>
        </Pressable>
        <Pressable {{#if (eq styling "nativewind")}}className="flex-row items-center justify-center gap-2 rounded-xl border border-gray-200 px-5 py-3"{{else}}style={styles.secondaryButton}{{/if}}>
          {{#if (eq icons "lucide")}}
          <Phone size={18} color="#374151" />
          {{/if}}
          <Text {{#if (eq styling "nativewind")}}className="font-medium text-gray-700"{{else}}style={styles.secondaryButtonText}{{/if}}>
            Call
          </Text>
        </Pressable>
      </View>
    </View>
  );
}

